  '偏': { parts: ["亻", "扁"], meanings: ["nghiêng lệch khỏi vạch tâm chuẩn"], mnemonic: "Lỗi dán tem nước lệch khỏi trục giữa vỏ mũ >1.0mm (贴花偏位) = LỆCH VỊ TRÍ (Thiên vị)" },
  '做': { parts: ["亻", "故"], meanings: ["người bắt tay thực thi hoàn tất"], mnemonic: "Đẩy hiệu suất xếp công-ten-nơ đạt tới 96% CBM (做到96%) = THỰC HIỆN ĐẠT TỚI" },
  '充': { parts: ["亠", "允"], meanings: ["lấp đầy trọn vẹn đủ thời gian"], mnemonic: "Sấy thoát ẩm đầy đủ 100% trước khi đưa vào lò UV (充分烘烤) = ĐẦY ĐỦ (Sung phân)" },
