  '净': { parts: ["冫", "争"], meanings: ["trong sạch tinh khiết không bọt nước"], mnemonic: "Vuốt sạch 100% bọt khí và nước dưới màng tem (刮净水汽) = SẠCH KĨ (Tịnh)" },
  '刮': { parts: ["舌", "刂"], meanings: ["bản gạt mềm", "đao (miết phẳng bề mặt)"], mnemonic: "Dùng gạt cao su miết sạch bọt nước khi dán tem nước (刮净水汽 / 刮水) = GẠT / VUỐT PHẲNG" },
  '到': { parts: ["至", "刂"], meanings: ["chí (đạt tới đích)", "chuẩn mục tiêu"], mnemonic: "Đạt đúng chỉ tiêu kỹ thuật 96% CBM hoặc 20N–50N (做到 / 二十到五十牛) = ĐẠT ĐẾN" },
  '十': { parts: ["一", "丨"], meanings: ["thập (con số 10 tròn trịa đủ mặt)"], mnemonic: "Thả rơi đủ 10 lần (1 góc 3 cạnh 6 mặt) theo chuẩn ISTA-1A (跌落十次) = MƯỜI (10 lần)" },
  '千': { parts: ["丿", "十"], meanings: ["thiên (con số 1,000 bền bỉ)"], mnemonic: "Thử đóng mở khóa cài bền bỉ 5,000 chu kỳ liên tục (五千次耐久) = NGHÌN (Thiên)" },
  '即': { parts: ["艮", "卩"], meanings: ["bắt tay hành động ngay tức khắc"], mnemonic: "Phát hiện lỗi là chặn cách ly ngay lập tức (立即拦截隔离) = TỨC THÌ (Lập tức)" },
  '及': { parts: ["丿", "乃"], meanings: ["nối tiếp bao gồm đầy đủ các mục"], mnemonic: "Kiểm tra đồng bộ áp dương, súng ion cùng lưới lọc sơn (及四百目过滤网) = CÙNG VỚI / VÀ" },
