  '哪': { parts: ["口", "那"], meanings: ["khẩu (hỏi chỉ đích danh vị trí lỗi)"], mnemonic: "Truy rõ khâu nào bất thường trong ép hơi nước EPS (哪里异常 / 哪三项) = Ở ĐÂU / MỤC NÀO" },
  '四': { parts: ["囗", "儿"], meanings: ["tứ (số 4 chuẩn mực công nghiệp)"], mnemonic: "Cốc đo độ nhớt Ford Cup #4, lưới lọc 400 mesh và cont 40HC/45HC (四号秒杯 / 四百目) = SỐ BỐN" },
  '场': { parts: ["土", "昜"], meanings: ["thổ (mặt bằng sản xuất thực tế)"], mnemonic: "Hiện trường dây chuyền sản xuất Gemba (现场排查) = HIỆN TRƯỜNG (Hiện trường)" },
  '如': { parts: ["女", "口"], meanings: ["đúng theo quy trình chuẩn mực"], mnemonic: "Triển khai đúng phương pháp chuẩn ISTA-1A (如何执行) = NHƯ THẾ NÀO" },
  '完': { parts: ["宀", "元"], meanings: ["miên", "nguyên (trọn vẹn 100% công đoạn)"], mnemonic: "Hoàn tất đóng gói thùng đầu tiên và ủ mẫu Lab (包装完成后) = HOÀN TẤT" },
  '宽': { parts: ["宀", "艹", "见"], meanings: ["kích thước chiều rộng thùng hàng"], mnemonic: "Tối ưu Dài × Rộng × Cao thùng khớp lòng công-ten-nơ (外箱长宽高) = CHIỀU RỘNG (Khoan)" },
  '就': { parts: ["京", "尤"], meanings: ["ngay lập tức dẫn tới hiện tượng"], mnemonic: "Hạt EPS thiếu kết dính hễ miết tay là rơi bở ngay (一搓就掉) = LIỀN / NGAY" },
  '常': { parts: ["尚", "巾"], meanings: ["trạng thái ổn định bình thường"], mnemonic: "Phát hiện sớm điểm bất thường thông số máy và trọng lượng (异常 = Abnormality) = THƯỜNG / BẤT THƯỜNG" },
  '并': { parts: ["丷", "开"], meanings: ["song hành thực hiện đồng bộ hai bước"], mnemonic: "Vừa pha chỉnh dung môi đồng thời hiệu chuẩn áp khí súng sơn = ĐỒNG THỜI (Tịnh)" },
  '序': { parts: ["广", "予"], meanings: ["nghiễm (xưởng)", "trình tự công đoạn SOP"], mnemonic: "Thứ tự thả rơi 1 góc - 3 cạnh - 6 mặt và công đoạn sản xuất (顺序 / 工序) = TRÌNH TỰ / CÔNG ĐOẠN" },
  '异': { parts: ["巳", "廾"], meanings: ["khác biệt lệch khỏi chuẩn bình thường"], mnemonic: "Chặn ngay hộp mũ lệch trọng lượng hoặc thông số hơi nước lạ (克重异常) = BẤT THƯỜNG (Dị)" },
  '彩': { parts: ["爫", "彡"], meanings: ["sắc màu in ấn đẹp mắt"], mnemonic: "Hộp màu bán lẻ đựng từng chiếc mũ bảo hiểm cao cấp (彩盒 = Color Box) = HỘP MÀU (Thái hộp)" },
  '必': { parts: ["心", "丿"], meanings: ["tâm", "phiệt (dứt khoát bắt buộc 100%)"], mnemonic: "Trước khi chạy hàng loạt bắt buộc kiểm chứng Lab 100% (必须验证) = BẮT BUỘC (Tất tu)" },
  '怎': { parts: ["乍", "心"], meanings: ["suy xét cách thức giải quyết vấn đề"], mnemonic: "Chỉnh thông số cốc giây và xử lý sự cố như thế nào (怎么调整) = THẾ NÀO" },
  '慢': { parts: ["忄", "曼"], meanings: ["từ tốn kéo dài thời gian bay hơi"], mnemonic: "Dung môi chậm khô giúp sơn tự chảy phẳng xóa sạch vỏ cam (慢干稀释剂) = CHẬM KHÔ (Mạn can)" },
  '截': { parts: ["隹", "戈"], meanings: ["chặn cắt đứt ngay trên băng chuyền"], mnemonic: "Chặn giữ tức thì lô sơn lỗi hoặc hộp thiếu phụ kiện (立即拦截) = CHẶN ĐỨNG (Lan tiệt)" },
  '执': { parts: ["扌", "丸"], meanings: ["thủ (nắm chắc)", "thực thi kỷ luật"], mnemonic: "Thực thi nghiêm ngặt bài test rơi thùng ISTA-1A & khu cách ly (执行测试) = THỰC THI (Chấp hành)" },
