  '损': { parts: ["扌", "员"], meanings: ["va chạm làm hư hại móp rách"], mnemonic: "Thùng carton sau 10 cú thả rơi ISTA-1A nguyên vẹn 0 rách vỡ (无破损) = HƯ HẠI (Phá tổn)" },
