  '效': { parts: ["交", "攵"], meanings: ["kết quả thực tế đạt được sau kiểm chứng"], mnemonic: "Hiệu quả khử bụi tĩnh điện của súng ion và khép kín 8D (除尘效果 / 有效闭环) = HIỆU QUẢ" },
  '整': { parts: ["束", "攵", "正"], meanings: ["chỉnh đốn ngay ngắn đúng chuẩn"], mnemonic: "Hiệu chỉnh lại độ nhớt sơn và mật độ EPS về đúng tâm chuẩn (调整) = ĐIỀU CHỈNH (Chỉnh)" },
  '断': { parts: ["米", "斤"], meanings: ["cân (rìu cắt)", "mặt cắt gãy ngang kiểm định"], mnemonic: "Bẻ gãy mặt cắt xốp EPS để chấm điểm độ kết dính hạt (掰断检查) = BẺ GÃY / MẶT CẮT" },
  '无': { parts: ["一", "尤"], meanings: ["vô (con số 0 tuyệt đối không có lỗi)"], mnemonic: "Thùng không rách, cont không lọt sáng và không thể lắp ngược (无破损 / 无漏光) = KHÔNG CÓ (Zero)" },
