  '最': { parts: ["日", "取"], meanings: ["chốt chặn sau cùng quan trọng nhất"], mnemonic: "Bước đối chiếu cuối cùng của Kho & QC trước khi bấm chì cont (最后核对) = CUỐI CÙNG / NHẤT" },
  '校': { parts: ["木", "交"], meanings: ["đối chiếu hiệu chuẩn về vạch chuẩn"], mnemonic: "Hiệu chuẩn lại áp suất khí phun sương súng sơn và thiết bị đo (校准雾化气压) = HIỆU CHUẨN" },
  '棱': { parts: ["木", "凌"], meanings: ["cạnh gấp giao nhau giữa hai mặt thùng"], mnemonic: "Thả rơi 3 cạnh thùng carton trong quy trình 1 góc 3 cạnh 6 mặt ISTA-1A (一角三棱六面) = CẠNH THÙNG" },
  '死': { parts: ["歹", "匕"], meanings: ["khoảng trống góc chết không xếp được hàng"], mnemonic: "Thiết kế sơ đồ xếp thùng sát trần giảm tối đa góc chết trong cont (少留死角) = GÓC CHẾT (Tử giác)" },
  '每': { parts: ["母", "丿"], meanings: ["mỗi từng đơn vị không bỏ sót"], mnemonic: "Đảm bảo mỗi một thùng mũ xuất đi đều đủ phụ kiện 100% (每箱出货) = MỖI / TỪNG THÙNG" },
  '比': { parts: ["匕", "匕"], meanings: ["hai đại lượng đặt cạnh nhau so sánh tỷ lệ"], mnemonic: "Pha dung môi theo đúng tỷ lệ phần trăm và đối chiếu phân tầng (按比例 / 对比) = TỶ LỆ / SO SÁNH" },
  '毫': { parts: ["高", "毛"], meanings: ["sợi lông mảnh = phần nghìn mét (mm)"], mnemonic: "Đơn vị đo chính xác từng mi-li-mét: tem nước ≤1.0mm, trượt MIPS 10–15mm (毫米 = mm) = MI-LI-MÉT" },
  '气': { parts: ["气"], meanings: ["khí (luồng hơi nước / khí nén áp suất)"], mnemonic: "Áp suất khí phun sương sơn và bọt hơi nước dưới tem (雾化气压 / 水汽) = KHÍ NÉN / HƠI" },
  '消': { parts: ["氵", "肖"], meanings: ["làm dịu triệt tiêu ánh phản xạ chói"], mnemonic: "Chất bột làm mờ trong công thức sơn mờ mũ bảo hiểm (消光粉 = Matting Agent) = TRIỆT TIÊU / LÀM MỜ" },
  '渍': { parts: ["氵", "责"], meanings: ["thủy (vết nước đọng ẩm bẩn trên sàn)"], mnemonic: "Kiểm tra sàn công-ten-nơ không có vết nước loang ẩm mốc (无漏光水渍) = VẾT NƯỚC ĐỌNG" },
  '港': { parts: ["氵", "巷"], meanings: ["thủy (bến nước sâu)", "hạng (luồng tàu biển)"], mnemonic: "Cảng biển quốc tế nơi kéo công-ten-nơ 45HC ra xuất tàu (发往港口) = CẢNG BIỂN (Cảng khẩu)" },
  '滤': { parts: ["氵", "虑"], meanings: ["thủy (dòng sơn đi qua)", "giữ sạch cặn bẩn"], mnemonic: "Lưới lọc 400 mesh chặn sạch hạt cặn trước khi vào súng sơn (过滤网) = LỌC SẠCH (Quá lự)" },
  '照': { parts: ["昭", "灬"], meanings: ["ánh sáng chiếu rõ / ống kính ghi hình"], mnemonic: "Chiếu tia cực tím UV và chụp ảnh bằng chứng số chì công-ten-nơ (照射 / 拍照核对) = CHIẾU SÁNG / CHỤP ẢNH" },
  '现': { parts: ["王", "见"], meanings: ["kiến (nhìn thấy trực tiếp ngay tại chỗ)"], mnemonic: "Kiểm tra trực tiếp tại hiện trường chuyền sơn và phát hiện lỗi (现场 / 出现 / 发现) = HIỆN TRƯỜNG / XUẤT HIỆN" },
  '由': { parts: ["日", "丨"], meanings: ["tự do không ngoại lực cản trở"], mnemonic: "Thả thùng hàng rơi tự do từ độ cao chuẩn ISTA-1A (自由跌落) = TỰ DO / DO BỞI" },
  '留': { parts: ["卯", "田"], meanings: ["giữ lại khoảng dư hoặc mẫu lưu"], mnemonic: "Xếp thùng khít trần để ít chừa lại khoảng trống góc chết (少留死角) = CHỪA LẠI / LƯU MẪU" },
  '目': { parts: ["目"], meanings: ["mục (mắt lưới lọc Mesh / con mắt quan sát)"], mnemonic: "Độ mịn lưới lọc sơn 400 lỗ/inch vuông chặn hạt bụi nhỏ (四百目过滤网 = 400 Mesh) = MẮT LƯỚI (Mesh)" },
  '稀': { parts: ["禾", "希"], meanings: ["làm loãng khoảng cách phân tử sơn"], mnemonic: "Dung môi pha loãng điều chỉnh giây chảy cốc Ford Cup #4 (稀释剂 = Thinner) = PHA LOÃNG" },
  '立': { parts: ["立"], meanings: ["lập (đứng thẳng vuông góc / ngay lập tức)"], mnemonic: "Xếp thùng đứng thẳng chịu lực nén tốt và hành động tức thì (立放 / 立即) = ĐỨNG THẲNG / LẬP TỨC" },
  '米': { parts: ["米"], meanings: ["mễ (đơn vị đo chiều dài chuẩn quốc tế mét)"], mnemonic: "Dung sai căn chỉnh tem nước trong phạm vi 1 mi-li-mét (一毫米 = 1mm) = MÉT (Mễ)" },
