  '误': { parts: ["讠", "吴"], meanings: ["độ sai lệch cần khóa chặt trong dung sai"], mnemonic: "Khống chế sai số lệch vị trí tem nước ≤1.0mm (对位误差) = SAI SỐ (Ngộ sai)" },
