  '雾': { parts: ["雨", "务"], meanings: ["vũ (hạt sương siêu mịn phun ra từ béc súng)"], mnemonic: "Áp suất khí xé tơi dòng sơn thành sương mịn chống sần vỏ cam (雾化气压) = PHUN SƯƠNG (Vụ hóa)" },
  '项': { parts: ["工", "页"], meanings: ["công", "hiệt (từng đầu mục kỹ thuật cụ thể)"], mnemonic: "3 hạng mục kiểm tra phòng sơn sạch và các mục chống ẩm cont (哪三项 / 安保项) = HẠNG MỤC" },
